import React, { useState } from 'react';
import { Box, Avatar, Typography, Dialog, DialogTitle, DialogContent, DialogContentText, DialogActions, Button, CircularProgress } from '@mui/material';
import { useNavigate } from 'react-router-dom';
import HomeIcon from '@mui/icons-material/Home';
import NotificationsIcon from '@mui/icons-material/Notifications';
import ArticleIcon from '@mui/icons-material/Article';
import LogoutIcon from '@mui/icons-material/Logout';
import { utilisateurService } from '../../services/utilisateurService';

interface LeftMenuProps {
    utilisateur: {
        id: number;
        pseudo: string;
        photo_profil: string | null;
    };
    activeView: 'actualites' | 'mes_publications';
    onViewChange: (view: 'actualites' | 'mes_publications') => void;
}

// Styles réutilisables
const menuItemStyles = {
    display: 'flex',
    alignItems: 'center',
    cursor: 'pointer',
    padding: '8px 12px',
    borderRadius: '12px',
    transition: 'all 0.3s ease',
    mb: 1,
    '&:hover': {
        background: 'rgba(119, 51, 153, 0.15)',
        transform: 'translateX(5px)'
    },
    '&:hover .menu-icon': {
        transform: 'scale(1.1)'
    },
    '&:hover .menu-text': {
        color: '#773399'
    }
};

const buttonStyles = {
    borderRadius: 45,
    borderColor: '#773399',
    color: '#773399',
    '&:hover': {
        borderColor: '#5a2a7a',
        color: '#5a2a7a',
        backgroundColor: 'rgba(119, 51, 153, 0.04)'
    }
};

const LeftMenu: React.FC<LeftMenuProps> = ({ utilisateur, activeView, onViewChange }) => {
    const navigate = useNavigate();
    const [logoutDialogOpen, setLogoutDialogOpen] = useState(false);
    const [loading, setLoading] = useState(false);

    const handleLogoutClick = () => {
        setLogoutDialogOpen(true);
    };

    const handleLogoutConfirm = async () => {
        setLoading(true);
        try {
            await utilisateurService.deconnexion();
            sessionStorage.clear();
            navigate('/login');
        } catch (error) {
            console.error('Erreur lors de la déconnexion', error);
        } finally {
            setLoading(false);
            setLogoutDialogOpen(false);
        }
    };

    const handleLogoutCancel = () => {
        setLogoutDialogOpen(false);
    };

    const avatarUrl = utilisateur.photo_profil
        ? `http://localhost:8080/uploads/${utilisateur.photo_profil}`
        : '/icons/green.jpg';

    const handleProfilClick = () => {
        navigate('/profil/settings');
    };

    return (
        <>
            <Box sx={{
                width: 280,
                background: 'linear-gradient(180deg, #ffffff 1%, #cfcfcf 43%, #999999 100%)',
                height: '100vh',
                position: 'sticky',
                top: 0,
                flexShrink: 0,
                display: 'flex',
                flexDirection: 'column'
            }}>
                {/* Logo */}
                <Box sx={{ 
                    display: 'flex', 
                    justifyContent: 'center', 
                    alignItems: 'center',
                    pt: 3,
                    pb: 2
                }}>
                    <img src="/icons/logo.png" alt="Logo" style={{ width: 199, height: 122 }} />
                </Box>

                {/* Profil cliquable */}
                <Box 
                    onClick={handleProfilClick}
                    sx={{ 
                        display: 'flex', 
                        flexDirection: 'column', 
                        alignItems: 'center',
                        mt: 2,
                        mb: 2,
                        cursor: 'pointer',
                        transition: 'all 0.3s ease',
                        '&:hover': {
                            '& .avatar': {
                                transform: 'scale(1.05)',
                                boxShadow: '0 6px 15px rgba(119, 51, 153, 0.3)'
                            },
                            '& .pseudo': {
                                color: '#773399',
                                textDecoration: 'underline'
                            }
                        }
                    }}
                >
                    <Avatar
                        src={avatarUrl}
                        className="avatar"
                        sx={{ 
                            width: 86, 
                            height: 88, 
                            border: '3px solid white', 
                            boxShadow: '0 4px 10px rgba(0,0,0,0.2)',
                            transition: 'transform 0.3s ease'
                        }}
                    />
                    <Typography 
                        className="pseudo"
                        sx={{
                            fontFamily: 'Poppins',
                            fontWeight: 600,
                            fontSize: 16,
                            color: '#333',
                            textAlign: 'center',
                            mt: 2,
                            transition: 'all 0.3s ease'
                        }}
                    >
                        @{utilisateur.pseudo}
                    </Typography>
                </Box>

                {/* Menu */}
                <Box sx={{ flex: 1, px: 3, mt: 2 }}>
                    <MenuItem
                        icon={<HomeIcon />}
                        label="Actualités"
                        isActive={activeView === 'actualites'}
                        onClick={() => onViewChange('actualites')}
                    />

                    <MenuItem
                        icon={<NotificationsIcon />}
                        label="Notification"
                        isActive={false}
                        onClick={() => {}}
                    />

                    <MenuItem
                        icon={<ArticleIcon />}
                        label="Mes publications"
                        isActive={activeView === 'mes_publications'}
                        onClick={() => onViewChange('mes_publications')}
                    />
                </Box>

                {/* Déconnexion */}
                <Box sx={{
                    px: 3,
                    pb: 4,
                    mt: 'auto'
                }}>
                    <Box
                        onClick={handleLogoutClick}
                        sx={{
                            display: 'flex',
                            alignItems: 'center',
                            cursor: 'pointer',
                            padding: '8px 12px',
                            borderRadius: '12px',
                            transition: 'all 0.3s ease',
                            '&:hover': {
                                background: 'rgba(119, 51, 153, 0.15)',
                                transform: 'translateX(5px)'
                            },
                            '&:hover .logout-icon': {
                                color: '#773399'
                            },
                            '&:hover .logout-text': {
                                color: '#773399'
                            }
                        }}
                    >
                        <LogoutIcon className="logout-icon" sx={{ width: 32, height: 32, color: '#666', transition: 'color 0.3s ease' }} />
                        <Typography className="logout-text" sx={{ ml: 2, fontFamily: 'Poppins', fontWeight: 600, fontSize: 16, color: '#333', transition: 'color 0.3s ease' }}>
                            Se déconnecter
                        </Typography>
                    </Box>
                </Box>
            </Box>

            {/* Dialogue de confirmation de déconnexion */}
            <Dialog open={logoutDialogOpen} onClose={handleLogoutCancel}>
                <DialogTitle sx={{ fontFamily: 'Poppins', fontWeight: 600 }}>
                    Déconnexion
                </DialogTitle>
                <DialogContent>
                    <DialogContentText sx={{ fontFamily: 'Poppins' }}>
                        Êtes-vous sûr de vouloir vous déconnecter ?
                    </DialogContentText>
                </DialogContent>
                <DialogActions>
                    <Button onClick={handleLogoutCancel} sx={buttonStyles}>
                        Annuler
                    </Button>
                    <Button 
                        onClick={handleLogoutConfirm} 
                        disabled={loading}
                        variant="contained"
                        sx={{
                            borderRadius: 45,
                            backgroundColor: '#773399',
                            '&:hover': { backgroundColor: '#5a2a7a' }
                        }}
                    >
                        {loading ? <CircularProgress size={24} color="inherit" /> : 'Se déconnecter'}
                    </Button>
                </DialogActions>
            </Dialog>
        </>
    );
};

interface MenuItemProps {
    icon: React.ReactNode;
    label: string;
    isActive: boolean;
    onClick: () => void;
}

const MenuItem: React.FC<MenuItemProps> = ({ icon, label, isActive, onClick }) => {
    return (
        <Box
            onClick={onClick}
            sx={{
                ...menuItemStyles,
                background: isActive ? 'rgba(119, 51, 153, 0.2)' : 'transparent',
                borderLeft: isActive ? '3px solid #773399' : '3px solid transparent'
            }}
        >
            <Box className="menu-icon" sx={{
                width: 32,
                height: 32,
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                color: isActive ? '#773399' : '#666',
                transition: 'transform 0.3s ease'
            }}>
                {icon}
            </Box>
            <Typography className="menu-text" sx={{
                ml: 2,
                fontFamily: 'Poppins',
                fontWeight: isActive ? 700 : 600,
                fontSize: 16,
                color: isActive ? '#773399' : '#333',
                transition: 'color 0.3s ease'
            }}>
                {label}
            </Typography>
        </Box>
    );
};

export default LeftMenu;
